def run_queue_ops(operations: list[tuple]) -> list:
    class MyQueue:
        def __init__(self):
            self.s1 = []
            self.s2 = []
        def enqueue(self, val):
            self.s1.append(val)
        def _transfer(self):
            if not self.s2:
                while self.s1:
                    self.s2.append(self.s1.pop())
        def dequeue(self):
            self._transfer()
            return self.s2.pop() if self.s2 else None
        def peek(self):
            self._transfer()
            return self.s2[-1] if self.s2 else None
        def is_empty(self):
            return not self.s1 and not self.s2

    q = MyQueue()
    res = []
    for op in operations:
        if op[0] == 'enqueue':
            q.enqueue(op[1])
            res.append(None)
        elif op[0] == 'dequeue':
            res.append(q.dequeue())
        elif op[0] == 'peek':
            res.append(q.peek())
        elif op[0] == 'is_empty':
            res.append(q.is_empty())
    return res
